
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_tfvw_opt_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_tfvw_opt", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([7.819547991028001e+01, 7.562409900843774e+01, 7.210571986780056e+01, 6.739550511285131e+01, 6.128363210577238e+01, 5.369825907590752e+01, 4.485810510401771e+01, 3.541482004180416e+01, 2.639054109753333e+01, 1.842532861729928e+01, 9.740030740143176e+00, 2.335594913591097e+00, 1.490215025831472e+00, 1.189609755788685e+00, 8.384022363346328e-01, 5.798852254383795e-01, 4.498378638519199e-01, 3.912418522611707e-01, 3.616282235914033e-01, 3.440368274585540e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


